css:
:scope{display:block;width:100%}
.pw{--ink:#010A12;--bone:#EDE6D8;--sand:#BBAFA3;--oxblood:#321013;--head:'Cormorant Garamond',serif;--body:'EB Garamond',serif;--label:'Montserrat',sans-serif;position:relative;font-family:var(--body);font-size:21px;line-height:1.5;font-weight:400;letter-spacing:0;-webkit-font-smoothing:antialiased;text-align:left}
.pw *{box-sizing:border-box}
:where(.pw p,.pw h1,.pw h2,.pw h3){margin:0;padding:0}
:where(.pw p,.pw li,.pw h1,.pw h2,.pw h3){text-wrap:wrap}
:where(.pw h1,.pw h2,.pw h3){color:inherit}
:where(.pw){overflow-wrap:normal}
.in{max-width:1200px;margin:0 auto;padding:0 32px}
.narrow{max-width:1000px}
.pad{padding:160px 0}
.kick{margin:0;font-family:var(--label);font-weight:400;font-size:12px;letter-spacing:.32em;text-transform:uppercase}
.rule{width:64px;height:1px;border:0;margin:28px 0 32px}
.pw h2{font-family:var(--head);font-weight:500;font-size:60px;line-height:1.08;letter-spacing:0;margin:0;text-wrap:balance;max-width:14em;text-indent:-.0333em}
.close{font-family:var(--head);font-style:italic;font-weight:500;font-size:34px;line-height:1.2;margin:72px 0 0}
.oxg{background:var(--oxblood);color:var(--bone)}
.oxg .kick{color:var(--sand)}
.oxg .rule{background:var(--sand)}
.sub2{font-family:var(--head);font-weight:500;font-size:32px;line-height:1.3;margin:24px 0 0;max-width:24em}
.cols2{display:grid;grid-template-columns:1fr 1fr;gap:48px;margin-top:64px}
.cols2 p{margin:0}
.js-rv .rv{opacity:0;transform:translateY(16px);transition:opacity 1.3s ease,transform 1.3s ease}
.js-rv .rv.on{opacity:1;transform:none}
.js-rv .d1{transition-delay:.12s}
@media (max-width:767px){.pw{font-size:19px}.in{padding:0 20px}.pad{padding:88px 0}.pw h2{font-size:40px}.close{font-size:27px;margin-top:44px}.sub2{font-size:25px}.cols2{grid-template-columns:1fr;gap:32px}}
@media (prefers-reduced-motion:reduce){.js-rv .rv{opacity:1;transform:none;transition:none}}
